inputs.customFunctionJavascriptFunction:
const raw = typeof $raw === "string"
  ? $raw
  : JSON.stringify($raw);

try {
  // 1. Check input
  if (!raw || !raw.trim()) {
    throw new Error("LLM Classification Agent returned empty input");
  }

  // 2. Remove optional Markdown code fences
  const cleaned = raw.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "");

  // 3. Parse JSON
  const data = JSON.parse(cleaned);

  // 4. Allowed classification values
  const allowed = {
    request_type: [
      "specific_purchase",
      "general_policy_question",
      "other",
      "unknown"
    ],
    purchase_category: [
      "goods",
      "construction_services",
      "professional_services",
      "other",
      "unknown"
    ],
    funding_source: [
      "local",
      "state",
      "federal",
      "unknown"
    ],
    payment_method: [
      "purchasing_card",
      "other",
      "unknown"
    ],
    exception_type: [
      "none",
      "blanket_order",
      "negotiated_contract",
      "used_equipment",
      "town_charter",
      "continuity_of_service",
      "emergency",
      "local_vendor_preference",
      "other"
    ]
  };

  // 5. Allowed query topics
  const topics = [
    "purchase_procedure",
    "spending_limits",
    "approvals",
    "bidding",
    "purchasing_card",
    "exceptions",
    "contracts",
    "retainage",
    "vendor_selection",
    "receiving_payment",
    "ethics_compliance",
    "others"
  ];

  // 6. Validate query_types
  if (
    !Array.isArray(data.query_types) ||
    !data.query_types.length ||
    !data.query_types.every(x => topics.includes(x))
  ) {
    throw new Error("Invalid query_types");
  }

  // 7. Validate categorical fields
  for (const [key, values] of Object.entries(allowed)) {
    if (!values.includes(data[key])) {
      throw new Error("Invalid " + key);
    }
  }

  // 8. Validate estimated_value
  if (
    typeof data.estimated_value !== "number" ||
    !Number.isFinite(data.estimated_value) ||
    data.estimated_value < -1
  ) {
    throw new Error("Invalid estimated_value");
  }

  // 9. Validate clarification_question
  if (typeof data.clarification_question !== "string") {
    throw new Error("Invalid clarification_question");
  }

  // 10. Return validated classification
  return JSON.stringify(data);

} catch (error) {
  // Show the actual error in Flowise for debugging
  throw new Error("JSON Parser failed: " + error.message);
}

