inputs.customFunctionJavascriptFunction:
try {
  const data = typeof $classification === "string"
    ? JSON.parse($classification)
    : $classification;

  // Check if clarification is required
  if (data.clarification_question?.trim()) {
    return "needs_clarification";
  }

  const amount = data.estimated_value;
  const category = data.purchase_category;

  let procurement_path = "policy_lookup";

  // State/Federal funding is outside this policy
  if (["state", "federal"].includes(data.funding_source)) {
    procurement_path = "outside_policy_scope";
  }
  // General questions go directly to policy retrieval
  else if (data.request_type === "general_policy_question") {
    procurement_path = "general_policy_lookup";
  }
  // Exceptions need separate review
  else if (data.exception_type !== "none") {
    procurement_path = "exception_review";
  }
  // Missing or unclear information
  else if (
    amount < 0 ||
    category === "unknown" ||
    category === "other"
  ) {
    procurement_path = "needs_review";
  }
  // Goods: $10,000 threshold
  else if (category === "goods") {
    procurement_path = amount <= 10000
      ? "section_IV_A"
      : "section_IV_B";
  }
  // Construction / Professional Services: $50,000 threshold
  else if (
    ["construction_services", "professional_services"]
      .includes(category)
  ) {
    procurement_path = amount <= 50000
      ? "section_V_A"
      : "section_V_B";
  }

  return procurement_path;

} catch (error) {
  return "classification_error";
}

